# scail2 — generated by tools/gen_model_py.py from the yaml
# cascade (2026-09-02 flip), then hand-edited since. The
# class IS the unit: family head → variants → quant cells;
# merged_defaults() walks the cascade. Parity pinned by
# tests/walls/suites/test_python_models.py + the http goldens.
#
# SSOT law: this file REPLACES model.yaml + variants/. A
# model.yaml reappearing next to it is a LOUD refusal.


from melite_models import  KnobRow,Model, LaneInputs, Variant, Cell, LoraRow, Genre, ClipType, Quant


class Scail2(Model):
    id = 'scail2-animate'
    genre = Genre.VIDEO
    label = 'SCAIL-2'
    description = 'SCAIL-2 character animation — drives a reference character from a video and colored mask.'
    engine = 'comfyui'
    card = 'video-gen'
    # loader facts the renderer reads; the family's extra
    # weights (VACE module / Lightning LoRA) ride defaults
    # + the renderer doc — the template is the SSOT graph
    lane_inputs = LaneInputs(
        unet='scail2_14B_fp8_scaled.safetensors',
        text_encoder='umt5_xxl_fp8_e4m3fn_converted.safetensors',
        clip_type=ClipType.WAN,
        vae='Wan2_1_VAE_bf16.safetensors',
    )
    form = 'form_video_director'
    defaults = dict(
            width=480,
            height=480,
            length=25,
            fps=24,
            steps=12,           # no distill LoRA on this estate — 25 for real work
            cfg=5.0,
            pose_strength=1.0,
            sampler='euler',
            scheduler='simple',
            seed=42,
        )
    # the CASCADE GATE (image-edit rework 2026-09-05) — this lane
    # ships a single ComfyUI UNETLoader configuration. The cell states
    # the TRUE quant tier the loader reads (no tier switch today); a
    # future second cell row lands as a real tier (the family grows).
    variants = (
        Variant(id='standard', label='Standard', route='scail2-animate', cells=(
            Cell(quant=Quant.FP8, label='FP8', route='scail2-animate', vram_peak_gb=24.0),
        )),
    )

    # the video-gen card surface for the scail2 arm (row 3,
    # 2026-09-06) — the wan block plus the driving-video pair
    # (pose_video feeds the VHS path loader, pose_strength the
    # SCAIL node).
    card_knobs = (
        KnobRow(card='prompt', inject='CLIPTextEncode.0.text', kind='s'),
        KnobRow(card='negative_prompt', inject='CLIPTextEncode.1.text', kind='s'),
        KnobRow(card='reference_image', inject='LoadImage.0.image', kind='s'),
        KnobRow(card='pose_video', inject='VHS_LoadVideoPath.0.video', kind='s'),
        KnobRow(card='pose_strength', inject='WanSCAILToVideo.0.pose_strength', kind='n'),
        KnobRow(card='width', inject='WanSCAILToVideo.0.width', kind='n'),
        KnobRow(card='height', inject='WanSCAILToVideo.0.height', kind='n'),
        KnobRow(card='length', inject='WanSCAILToVideo.0.length', kind='n'),
        KnobRow(card='fps', inject='VHS_VideoCombine.0.frame_rate', kind='n'),
        KnobRow(card='seed', inject='KSampler.0.seed', kind='n'),
        KnobRow(card='steps', inject='KSampler.0.steps', kind='n'),
        KnobRow(card='cfg', inject='KSampler.0.cfg', kind='n'),
        KnobRow(card='sampler', inject='KSampler.0.sampler_name', kind='s'),
        KnobRow(card='scheduler', inject='KSampler.0.scheduler', kind='s'),
    )


